insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'ms_theatre1_v1'
from (values
('117.211.c.1.A',2,'A student remembers how her stomach felt before a big test and uses that feeling to play a nervous character. This technique is called:','["emotional recall", "sensory guessing", "blocking", "script cutting"]'::jsonb,0,'Emotional recall draws on a real feeling to build a character.','original'),
('117.211.c.1.A',2,'Remembering the smell of rain and the sound of thunder to help play a character caught in a storm is called:','["stage lighting", "sensory recall", "costume design", "voice projection"]'::jsonb,1,'Sensory recall uses the five senses to build character detail.','original'),
('117.211.c.1.B',1,'Acting out pulling a heavy rope without any rope on stage uses the skill of:','["singing", "prompting", "mime", "set painting"]'::jsonb,2,'Mime shows objects and actions without props or words.','original'),
('117.211.c.1.B',2,'Showing, with only your body, that you are opening a stuck door expands your:','["ticket sales", "lighting plan", "script length", "body awareness"]'::jsonb,3,'Mime helps actors control and notice their bodies.','original'),
('117.211.c.1.C',2,'Students hear a slow, sad piece of music and move across the floor in response. They are responding to:','["sound with movement", "a menu", "a math problem", "a calendar"]'::jsonb,0,'Music can inspire movement choices.','original'),
('117.211.c.1.C',2,'Reading a poem and then acting out its images with movement is a way to respond to:','["a spotlight", "the written word", "a stage curtain", "a ticket"]'::jsonb,1,'Text can inspire movement.','original'),
('117.211.c.1.D',2,'The vocal fold vibrations that make sound happen in the:','["elbow", "stomach", "larynx", "knee"]'::jsonb,2,'Sound is produced by vibrating folds in the larynx.','original'),
('117.211.c.1.D',2,'Using breath from the diaphragm helps an actor create a voice that is:','["silent", "strained", "weak and breathy", "strong and supported"]'::jsonb,3,'Breath support improves projection.','original'),
('117.211.c.1.E',1,'The area of the stage closest to the audience is called:','["downstage", "offstage", "backstage", "upstage"]'::jsonb,0,'Downstage is toward the audience.','original'),
('117.211.c.1.E',2,'The area hidden from the audience at the sides of the stage is the:','["pit", "wings", "apron", "balcony"]'::jsonb,1,'The wings are the side offstage areas.','original'),
('117.211.c.1.F',3,'The three main parts of a plot, in order, are usually the beginning, the middle with rising conflict, and the:','["rehearsal", "intermission", "resolution", "audition"]'::jsonb,2,'Plots end with a resolution.','original'),
('117.211.c.1.F',3,'In a play, the most intense point of the conflict is the:','["cue", "costume", "prologue", "climax"]'::jsonb,3,'The climax is the highest tension point.','original'),
('117.211.c.2.A',1,'Before acting, a student warms up the voice and body to avoid:','["strain and injury", "learning lines", "rehearsal", "applause"]'::jsonb,0,'Warm-ups protect the voice and body.','original'),
('117.211.c.2.A',2,'Safe use of the body in a stage fight includes:','["surprise hits", "agreed, slow, rehearsed movements", "no practice", "real force"]'::jsonb,1,'Stage movement must be controlled and planned.','original'),
('117.211.c.2.B',2,'A student describes a character as a shy twelve-year-old who lives on a farm with his grandfather. She is:','["designing a poster", "building a set only", "describing a character and surroundings", "pricing tickets"]'::jsonb,2,'Describing characters and settings clarifies imagination.','original'),
('117.211.c.2.B',2,'Clearly describing how two characters are related, such as siblings who argue, helps actors show their:','["prop weight", "stage size", "costume tags", "relationship"]'::jsonb,3,'Relationships guide acting choices.','original'),
('117.211.c.2.C',2,'An actor chooses a slow walk and a quiet voice to portray an old character from a story. She is selecting:','["movement and dialogue choices", "a stage color", "a program font", "a ticket price"]'::jsonb,0,'Choices of movement and speech show character.','original'),
('117.211.c.2.C',3,'A character drawn from a folktale is shown as sly. A good movement choice would be:','["a deep bow", "quick glances and careful steps", "frozen stillness", "loud stomping"]'::jsonb,1,'Movement matches personality.','original'),
('117.211.c.2.D',2,'Students act out a scene from a favorite book. They are:','["repairing a set", "buying a prop", "dramatizing a literary selection", "writing a ticket"]'::jsonb,2,'Dramatization brings literature to life.','original'),
('117.211.c.2.D',2,'Pretending to be a restaurant worker during a class game is an example of:','["a rehearsal for a musical", "a lighting cue", "a final exam", "dramatic play imitating life"]'::jsonb,3,'Dramatic play imitates real life.','original'),
('117.211.c.2.E',2,'A student shows excitement with a big smile, quick steps and a rising voice. She is expressing:','["an emotion with movement and dialogue", "an exit", "a prop list", "a stage direction"]'::jsonb,0,'Interpretive movement and voice show emotion.','original'),
('117.211.c.2.E',3,'To express the idea of freedom without words, an actor might:','["curl tightly", "stretch wide and move openly", "hide the face", "stay frozen"]'::jsonb,1,'Open movement suggests freedom.','original'),
('117.211.c.2.F',2,'A group invents a setting at the bottom of the sea and decides how the characters move there. They are creating:','["a budget", "a schedule", "environments, characters and actions", "a receipt"]'::jsonb,2,'Creating a world involves environment, characters and actions.','original'),
('117.211.c.2.F',3,'Creating a character who is a cranky lighthouse keeper requires choices about voice, posture and:','["parking", "font", "tuition", "what the character wants"]'::jsonb,3,'Character wants drive actions.','original'),
('117.211.c.3.A',3,'A group works together to build a scene with a character, a place, an action and a theme. They are creating collaboratively and using:','["safe use of the voice and body", "no plan", "random shouting", "unsafe moves"]'::jsonb,0,'Collaboration requires safe, focused work.','original'),
('117.211.c.3.A',3,'A theme in a scene is the:','["costume color", "main idea or message", "stage size", "ticket cost"]'::jsonb,1,'A theme is the underlying idea.','original'),
('117.211.c.3.B',2,'To suggest a forest with few materials, students might use:','["real trees", "a cruise ship", "a few cutout trees and sound effects", "a bank vault"]'::jsonb,2,'Simple elements can suggest an environment.','original'),
('117.211.c.3.B',2,'A suitable environment for a scene set in a kitchen includes:','["a spaceship panel", "a throne", "a ski lift", "a table, chairs and pretend dishes"]'::jsonb,3,'Environments fit the story.','original'),
('117.211.c.3.C',2,'A group plans a short dramatization by first deciding who, where and:','["what happens", "who sells tickets", "what color the program is", "how much it costs"]'::jsonb,0,'Planning covers characters, setting and action.','original'),
('117.211.c.3.C',2,'When collaborating, students make plans by:','["avoiding the group", "listening to each other''s ideas", "ignoring the plan", "talking over others"]'::jsonb,1,'Collaboration involves listening.','original'),
('117.211.c.3.D',2,'Using a microphone and a spotlight in a live show is an example of using:','["a pencil", "a crayon", "technology in theatre", "a ruler"]'::jsonb,2,'Sound and lights are theatre technology.','original'),
('117.211.c.3.D',2,'Recording a scene on a tablet to watch later is a way to use technology in:','["a gym", "a cafeteria", "a math lab", "video as a theatre tool"]'::jsonb,3,'Video helps review performances.','original'),
('117.211.c.4.A',3,'A play that shows how families lived long ago reflects theatre''s role as a mirror of:','["history, society and culture", "classroom seats", "lunch menus", "parking rules"]'::jsonb,0,'Theatre reflects its time and culture.','original'),
('117.211.c.4.A',3,'A play from a different culture helps students learn about:','["a phone plan", "that culture''s traditions", "a tax form", "a train timetable"]'::jsonb,1,'Plays often show cultural traditions.','original'),
('117.211.c.4.B',3,'A key development in film that changed storytelling was the addition of:','["stage curtains", "wooden boxes", "recorded sound", "costume tags"]'::jsonb,2,'Sound film changed the medium.','original'),
('117.211.c.4.B',3,'Television and electronic media influence theatre by:','["removing scripts", "hiding actors", "ending all plays", "reaching larger audiences and offering new styles"]'::jsonb,3,'Media influence storytelling and audiences.','original'),
('117.211.c.5.A',1,'Good audience etiquette during a play includes:','["staying quiet and turning off phones", "kicking seats", "texting", "talking"]'::jsonb,0,'Audience etiquette respects performers.','original'),
('117.211.c.5.A',1,'When the actors take their bows, the audience should:','["chat loudly", "applaud", "boo", "leave early"]'::jsonb,1,'Applause shows appreciation.','original'),
('117.211.c.5.B',3,'A student writes that the actor''s voice was loud and clear, her gestures were large, and the lights changed color. She is observing the aural, kinetic and:','["menu parts", "parking parts", "visual parts", "financial parts"]'::jsonb,2,'Observations cover visual, aural, oral and kinetic elements.','original'),
('117.211.c.5.B',3,'A simple oral observation of a play might say:','["It is on a stage.", "It was a thing.", "I do not know.", "I noticed the actor used a slow walk to show she was tired."]'::jsonb,3,'Specific observations name what you saw or heard.','original'),
('117.211.c.5.C',2,'Costumes, props, lights and sound are all:','["production elements", "ticket types", "program ads", "audience members"]'::jsonb,0,'Production elements support a performance.','original'),
('117.211.c.5.C',2,'A film and a play both use:','["only live crowds", "actors and a script", "only paper", "only stage curtains"]'::jsonb,1,'Both rely on performers and written material.','original'),
('117.211.c.5.D',2,'The person in charge of guiding the actors and the vision of a play is the:','["audience", "usher", "director", "ticket taker"]'::jsonb,2,'The director leads the creative vision.','original'),
('117.211.c.5.D',2,'The person who keeps rehearsals organized and calls cues during a show is the:','["costume critic", "ticket seller", "parking attendant", "stage manager"]'::jsonb,3,'The stage manager runs rehearsals and performances.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Fine Arts' and d.language = 'en'
on conflict (fingerprint) do nothing;
